-- Source: GFI Trade-Related Illicit Financial Flows Data (25 rows)
-- Generated by gen_mart_models.py

-- FILTER (2026-08-25 verification): this is not trade data. All 25 landing rows
-- have COUNTRY, YEAR, ILLICIT_FLOW_VALUE, and FLOW_DIRECTION blank -- the loader's
-- portal crawl of gfintegrity.org captured site chrome (nav links: "GFI Events",
-- "Careers", "Anti-Corruption"; footer boilerplate: the EIN/LEI disclosure, the
-- Creative Commons notice) into DATA_SOURCE_NOTES instead of the actual
-- country-by-country flow table. One single load run, no real values anywhere in
-- the table. Root cause is upstream of dbt (a bad crawl target, not a bad model
-- transform) and cannot be fixed here, so rows with no country are dropped
-- explicitly rather than left to collide on blank keys -- this mart is correctly
-- empty until the source is re-crawled against the real data table.
with source as (
    select * from {{ source('ripple_raw', 'INTL_GFI_TRADE') }}
    where nullif(trim(COUNTRY), '') is not null
)

select
    COUNTRY as country,
    try_to_number("YEAR") as year,
    try_to_double(ILLICIT_FLOW_VALUE) as illicit_flow_value,
    FLOW_DIRECTION as flow_direction,
    DATA_SOURCE_NOTES as data_source_notes
from source
